:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  max-width: 480px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  color: var(--accent);
  letter-spacing: 1px;
}

.score {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text);
}

.board-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  overflow: hidden;
  background: var(--grid);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 16px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--accent);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--muted);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn {
  background: transparent;
  border: 2px solid var(--accent);
  color: var(--accent);
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 24px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
  font-family: inherit;
}

.btn:hover {
  background: var(--accent);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.btn.primary {
  background: var(--accent);
  color: var(--bg);
}

.btn.primary:hover {
  background: var(--text);
  border-color: var(--text);
  color: var(--bg);
}

.btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--bg);
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 8px 16px;
    font-size: 0.9rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayMessage = document.getElementById('overlayMessage');
  const overlayButton = document.getElementById('overlayButton');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 140;

  let snake, food, direction, nextDirection, score, isPaused, isGameOver, loopId;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    isPaused = true;
    isGameOver = false;
    scoreEl.textContent = '0';
    spawnFood();
    updatePauseButton();
    showOverlay('How to Play', 'Use arrow keys to move.<br>Press Space or click Pause to start.', 'Start Game');
    draw();
    stopLoop();
  }

  function spawnFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4ecca3' : '#3ba882';
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function step() {
    if (isPaused || isGameOver) return;

    direction = nextDirection;
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      spawnFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function gameOver() {
    isGameOver = true;
    stopLoop();
    showOverlay('Game Over', 'Final score: ' + score + '<br>Press Restart to play again.', 'Restart');
  }

  function startLoop() {
    stopLoop();
    loopId = setInterval(step, TICK_MS);
  }

  function stopLoop() {
    if (loopId) {
      clearInterval(loopId);
      loopId = null;
    }
  }

  function showOverlay(title, message, buttonText) {
    overlayTitle.textContent = title;
    overlayMessage.innerHTML = message;
    overlayButton.textContent = buttonText;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function updatePauseButton() {
    pauseBtn.textContent = isPaused ? 'Resume' : 'Pause';
    pauseBtn.setAttribute('aria-pressed', isPaused ? 'false' : 'true');
  }

  function togglePause() {
    if (isGameOver) return;
    isPaused = !isPaused;
    updatePauseButton();
    if (isPaused) {
      stopLoop();
      showOverlay('Paused', 'Press Space or click Resume to continue.', 'Resume');
    } else {
      hideOverlay();
      startLoop();
    }
  }

  function restart() {
    init();
    isPaused = false;
    updatePauseButton();
    hideOverlay();
    startLoop();
  }

  function setDirection(dx, dy) {
    if (isPaused || isGameOver) return;
    if (dx === -direction.x && dy === -direction.y) return;
    nextDirection = { x: dx, y: dy };
  }

  document.addEventListener('keydown', function (e) {
    const key = e.key;
    if (key === 'ArrowUp') { e.preventDefault(); setDirection(0, -1); }
    else if (key === 'ArrowDown') { e.preventDefault(); setDirection(0, 1); }
    else if (key === 'ArrowLeft') { e.preventDefault(); setDirection(-1, 0); }
    else if (key === 'ArrowRight') { e.preventDefault(); setDirection(1, 0); }
    else if (key === ' ') { e.preventDefault(); togglePause(); }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  overlayButton.addEventListener('click', function () {
    if (isGameOver) {
      restart();
    } else {
      togglePause();
    }
  });

  init();
})();
